class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


def merge_two_lists(first, second):
    dummy = tail = ListNode()              # a stand-in before the real head, so the first node needs no special case
    while first is not None and second is not None:
        if first.val <= second.val:        # <= keeps equal values in their original order
            tail.next, first = first, first.next
        else:
            tail.next, second = second, second.next
        tail = tail.next
    tail.next = first if first is not None else second    # one list is used up: attach what is left of the other
    return dummy.next
